/*
 * Pictures that stand in for an icon (a joke asked for by Jean, 19/10/2026): the soprano saxophone shows a photograph of the soprano saxophonist
 * Kenny G (96 x 96 JPEG, ~3196 bytes) unless the device setting is off (then it uses the clarinet icon).
 *
 * LICENCE: the photograph is "KennyGHWOFMay2013.jpg" by Angela George, Wikimedia Commons, CC BY-SA 3.0
 * (https://creativecommons.org/licenses/by-sa/3.0/). Changes: cropped to a square and reduced to 96 x 96 pixels. The reduced picture stays under
 * CC BY-SA 3.0 (see LICENSES/KennyG-photo-CC-BY-SA-3.0.txt); the credit is shown in the settings panel (ICON_PHOTO_CREDITS).
 * (An earlier version used a press photograph supplied by Jean; it was replaced by this free one.)
 */
export const ICON_PHOTOS = Object.freeze({
  'soprano-photo': 'data:image/jpeg;base64,',
});

export const ICON_PHOTO_CREDITS = Object.freeze({
  'soprano-photo': Object.freeze({
    author: 'Angela George', license: 'CC BY-SA 3.0', licenseUrl: 'https://creativecommons.org/licenses/by-sa/3.0/',
    source: 'https://commons.wikimedia.org/wiki/File:KennyGHWOFMay2013.jpg',
  }),
});

export const photoOf = (name) => ICON_PHOTOS[name] ?? null;
